mapper.select:
select a.id,
       a.create_date,
       a.update_date,
       a.sec_uid,
       a.home_url,
       a.live_url,
       a.anchor_name,
       a.debut_date,
       a.anchor_avatar,
       a.platform,
       a.anchor_number,
       a.trade_id,
       a.company_id,
       a.dept_id,
       a.team_id
from live_room as a


        left

    join manager_connector as b on a.id = b.target_id and b.manager_type = 4  and b.is_deleted = 0 and b.employee_id = #{req.currentUserId}

where a.is_deleted = 0
  and a.tenant_id = #{tenantId}

    and a.anchor_name like concat('%', #{req.anchorName}, '%')


    and a.anchor_number like concat(#{req.anchorNumber}, '%')


    and a.company_id = #{req.companyId}



    and a.dept_id = #{req.deptId}




            or b.employee_id = #{req.currentUserId}


            or a.company_id in (

                #{item}

            )


            or a.dept_id in (

                #{item}

            )


            or a.team_id in (

                #{item}

            )





    and a.team_id = #{req.teamId}



    and a.platform = #{req.platform}


    and a.account_status = #{req.accountStatus}

order by a.id desc

select distinct live_room_id from schedule_employee where is_deleted = 0 and employee_id = #{employeeId}

      and position_id = #{positionId}


      and work_day >= #{deadlineDay}

  limit 1000

select distinct live_room_id, employee_id from schedule_employee where is_deleted = 0 and employee_id in

  #{item}


      and work_day >= #{deadlineDay}


      and position_id = #{positionId}

limit 10000

select a.id,
a.create_date,
a.update_date,
a.sec_uid,
a.home_url,
a.live_url,
a.anchor_name,
a.debut_date,
a.anchor_avatar,
a.platform,
a.anchor_number,
a.trade_id,
a.company_id,
a.dept_id,
a.team_id
from live_room as a


        left

    join manager_connector as b on a.id = b.target_id and b.manager_type = 4 and b.employee_id = #{req.currentUserId} and b.is_deleted = 0

where a.is_deleted = 0
and a.tenant_id = #{req.tenantId}

    and (
        a.anchor_name like concat('%', #{req.keyword}, '%')
        or a.anchor_number like concat('%', #{req.keyword}, '%')
    )


    and a.company_id = #{req.companyId}



    and a.dept_id = #{req.deptId}




            or b.employee_id = #{req.currentUserId}


            or a.company_id in (

                #{item}

            )


            or a.dept_id in (

                #{item}

            )


            or a.team_id in (

                #{item}

            )





    and a.team_id = #{req.teamId}



    and a.platform = #{req.platform}


    and a.account_status = #{req.accountStatus}

limit #{req.limit}

select a.id, a.create_date, a.update_date, a.sec_uid, a.home_url, a.live_url, a.anchor_name, a.debut_date, a.anchor_avatar, a.platform, a.anchor_number, a.trade_id, a.company_id, a.dept_id, a.team_id from live_room as a
LEFT JOIN ( SELECT live_room_id, COALESCE(SUM(view_count), 0) AS todayViewCount, COALESCE(SUM(sales_revenue), 0) AS todaySalesRevenue, COALESCE(SUM(refund), 0) AS todayRefund, COALESCE(SUM(net_sales), 0) AS todayNetSales, COALESCE(SUM(investment), 0) AS todayInvestment FROM session_performance WHERE tenant_id = #{tenantId} AND stats_date = CURDATE() AND is_deleted = 0 GROUP BY live_room_id ) sp_today ON a.id = sp_today.live_room_id
left
join manager_connector as b on a.id = b.target_id and b.manager_type = 4 and b.is_deleted = 0 and b.employee_id = #{req.currentUserId}
where a.is_deleted = 0 and a.tenant_id = #{tenantId}
and a.anchor_name like concat('%', #{req.anchorName}, '%')
and a.anchor_number like concat(#{req.anchorNumber}, '%')
and a.company_id = #{req.companyId}
and a.dept_id = #{req.deptId}
or b.employee_id = #{req.currentUserId}
or a.company_id in (
#{item}
)
or a.dept_id in (
#{item}
)
or a.team_id in (
#{item}
)
and a.team_id = #{req.teamId}
and a.platform = #{req.platform}
and a.account_status = #{req.accountStatus}
ORDER BY
sp_today.todayViewCount sp_today.todaySalesRevenue sp_today.todayRefund sp_today.todayNetSales sp_today.todayInvestment a.id
ASC DESC
